104	  async applyBootStateIfNeeded(engine: Engine): Promise<void> {
105	    const adapter = await this._getAdapter();
106	    await adapter?.applyBootStateIfNeeded?.(engine);
107	  }
108	
109	  async startPreviewIfNeeded(engine: Engine): Promise<void> {
110	    const adapter = await this._getAdapter();
111	    await adapter?.startPreviewIfNeeded?.(engine);
112	  }
