138	  syncScene<TSceneKey extends string, TSheetId extends string>(
139	    engine: Engine,
140	    sceneKey: TSceneKey,
141	    progress: number,
142	    onSheetChange: (sheetId: TSheetId | null) => void,
143	  ): void {
