145	    void this._syncScene(engine, sceneKey, progress, requestId, onSheetChange);
146	  }
147	
148	  private _getAdapter(): Promise<PageTheatreAdapter | null> {
149	    if (this._adapterPromise) return this._adapterPromise;
150	    this._adapterPromise = this._createAdapter();
151	    return this._adapterPromise;
152	  }
153	
154	  private async _createAdapter(): Promise<PageTheatreAdapter | null> {
155	    const pageType = this._pageId;
156	    if (!pageType) return null;
157	    const factory = PAGE_THEATRE_ADAPTER_FACTORIES[pageType];
158	    if (!factory) return null;
159	    return factory();

155	    const pageType = this._pageId;
156	    if (!pageType) return null;
157	    const factory = PAGE_THEATRE_ADAPTER_FACTORIES[pageType];
158	    if (!factory) return null;
159	    return factory();
160	  }
161	
162	  private async _getSceneSyncPort(): Promise<PageSceneSyncPort<string, string> | null> {
163	    if (this._sceneSyncPortPromise) return this._sceneSyncPortPromise;
164	    this._sceneSyncPortPromise = this._createSceneSyncPort();
165	    return this._sceneSyncPortPromise;
166	  }
167	
168	  private async _createSceneSyncPort(): Promise<PageSceneSyncPort<string, string> | null> {
169	    const adapter = await this._getAdapter();
170	    return (await adapter?.getSceneSyncPort?.()) ?? null;
171	  }
172	
173	  private async _syncScene<TSceneKey extends string, TSheetId extends string>(
174	    engine: Engine,
175	    sceneKey: TSceneKey,
176	    progress: number,
177	    requestId: number,
178	    onSheetChange: (sheetId: TSheetId | null) => void,
179	  ): Promise<void> {
180	    const port = await this._getSceneSyncPort();
181	    if (!port || requestId !== this._sceneRequestId) return;
182	    onSheetChange(port.apply(engine, sceneKey, progress) as TSheetId | null);
183	  }
184	
185	  private async _disposeAsync(): Promise<void> {
186	    const adapter = await this._getAdapter();
187	    await adapter?.stopPreview?.();
188	  }
