493	  private _resolvePreviewRangeByTrackFilter(
494	    sheetId: MainTheatreSheetId,
495	    sheetLength: number,
496	    shouldIncludeTrack?: (debugName: string) => boolean,
497	  ): MainTheatrePlaybackRange | null {
498	    const tracksByObject = this._readSheetTracksByObject(sheetId);
499	    const objectTracks = tracksByObject?.[MAIN_THEATRE_OBJECT_ID];
500	    if (!objectTracks || typeof objectTracks !== "object") return null;
501	    const trackData = (objectTracks as Record<string, unknown>).trackData;
502	    if (!trackData || typeof trackData !== "object") return null;
503	    let minPosition = Number.POSITIVE_INFINITY;
504	    let maxPosition = Number.NEGATIVE_INFINITY;
505	    Object.values(trackData as Record<string, unknown>).forEach(
506	      (trackState) => {
507	        if (!trackState || typeof trackState !== "object") return;
508	        const debugName = (trackState as Record<string, unknown>).__debugName;
509	        if (
510	          shouldIncludeTrack &&
511	          (typeof debugName !== "string" || !shouldIncludeTrack(debugName))
512	        ) {
513	          return;
514	        }
515	        const keyframes = (trackState as Record<string, unknown>).keyframes;
516	        if (!Array.isArray(keyframes)) return;
517	        const positions = keyframes
518	          .map((keyframe) => {
519	            if (!keyframe || typeof keyframe !== "object") return null;
520	            const position = (keyframe as Record<string, unknown>).position;
521	            return typeof position === "number" ? position : null;
522	          })
523	          .filter(
524	            (position): position is number =>
525	              typeof position === "number" && Number.isFinite(position),
526	          );
527	        if (positions.length < 2) return;
528	        minPosition = Math.min(minPosition, ...positions);
529	        maxPosition = Math.max(maxPosition, ...positions);
530	      },
531	    );
532	    if (!Number.isFinite(minPosition) || !Number.isFinite(maxPosition))
533	      return null;
534	    if (maxPosition <= minPosition) return null;
535	    return {
536	      start: this._clampPosition(minPosition, sheetLength),
537	      end: this._clampPosition(maxPosition, sheetLength),
538	    };
539	  }
