561	  private _clampPosition(position: number, length: number): number {
562	    if (!Number.isFinite(length) || length <= 0) return 0;
563	    if (!Number.isFinite(position)) return 0;
564	    if (position <= 0) return 0;
565	    if (position >= length) return length;
566	    return position;
567	  }
