7	export class ObjectConfigRuntime {
8	  resolve(
9	    objectId: keyof ObjectOptionsByKey,
10	    pageOptions: PageConfig["objectOptions"] | undefined,
11	    initialState: PageConfig["initialState"] | undefined,
12	  ): ObjectResolvedConfig {
13	    const merged = this._mergeSettings(
14	      this._getObjectSetting(objectId),
15	      this._mergeSettings(
16	        this._resolvePageOption(objectId, pageOptions),
17	        this._resolveInitialStateOverride(initialState, objectId as ObjectId),
18	      ),
19	    );
20	    const resolved = this._applyPerformanceOverrides(objectId, merged);
21	    if (!resolved) return {};
22	    const { effects, ...options } = resolved;
23	    return {
24	      options: Object.keys(options).length > 0 ? options : undefined,
25	      effects: this._isPlainRecord(effects) ? effects : undefined,
26	    };
27	  }
28	
29	  private _getObjectSetting(
30	    objectId: keyof ObjectOptionsByKey,
31	  ): Record<string, unknown> | undefined {
32	    return OBJECT_CONFIG[objectId] as Record<string, unknown> | undefined;
33	  }
34	
35	  private _resolvePageOption(
36	    objectId: keyof ObjectOptionsByKey,
37	    pageOptions: PageConfig["objectOptions"] | undefined,
38	  ): Record<string, unknown> | undefined {
39	    return pageOptions?.[objectId] as Record<string, unknown> | undefined;
40	  }
41	
42	  private _resolveInitialStateOverride(
43	    initialState: PageConfig["initialState"] | undefined,
44	    objectId: ObjectId,
45	  ): Record<string, unknown> | undefined {
46	    const state = initialState?.[objectId];
47	    if (!this._isPlainRecord(state)) return undefined;
48	
49	    const override: Record<string, unknown> = {};
50	    if (this._isPlainRecord(state.position)) {
51	      override.position = { ...state.position };
52	    }
53	    if (this._isPlainRecord(state.rotation)) {
54	      override.rotation = { ...state.rotation };
55	    }
56	    if (this._isPlainRecord(state.scale)) {
57	      override.scale = { ...state.scale };
58	    }
59	    if (typeof state.visible === "boolean") {
60	      override.visible = state.visible;
61	    }
62	
63	    return Object.keys(override).length > 0 ? override : undefined;
64	  }
65	
66	  private _mergeSettings(
67	    base: Record<string, unknown> | undefined,
68	    override: Record<string, unknown> | undefined,
69	  ): Record<string, unknown> | undefined {
70	    if (!base) return override ? { ...override } : undefined;
71	    if (!override) return { ...base };
72	
73	    const merged: Record<string, unknown> = { ...base };
74	    for (const [key, value] of Object.entries(override)) {
75	      const current = merged[key];
76	      merged[key] =
77	        this._isPlainRecord(current) && this._isPlainRecord(value)
78	          ? this._mergeSettings(current, value)
79	          : value;
80	    }
81	    return merged;
82	  }
83	
84	  private _applyPerformanceOverrides(
85	    objectId: keyof ObjectOptionsByKey,
86	    resolved: Record<string, unknown> | undefined,
87	  ): Record<string, unknown> | undefined {
88	    if (!resolved) return undefined;
89	    const performance = ResponsiveRuntime.getDefault().getSnapshot().performance;
90	    const next = { ...resolved };
91	
92	    if (objectId === "clouds") {
93	      next.cloudCount = performance.cloudCount;
94	    }
95	    if (objectId === "cloudScene") {
96	      next.cloudCount = Math.round(performance.cloudCount * 10);
97	    }
98	
99	    return next;
100	  }
101	
102	  private _isPlainRecord(value: unknown): value is Record<string, unknown> {
103	    if (value == null || typeof value !== "object" || Array.isArray(value)) {
104	      return false;
105	    }
106	    const proto = Object.getPrototypeOf(value);
107	    return proto === Object.prototype || proto === null;
108	  }
